BEGIN
 IF current_setting('xflow.remediation.target_project_ref',true) IS DISTINCT FROM 'mjfzoikkoykszxzuebdf' OR current_setting('xflow.remediation.change_ref',true) IS DISTINCT FROM 'REVIEW_DOMAIN_AUTHORITY_CONTAINMENT_V1' THEN RAISE EXCEPTION 'BATCH_TARGET_MARKER_STOP'; END IF;
 IF current_user <> 'postgres' THEN RAISE EXCEPTION 'EXPECTED_POSTGRES_OWNER_ROLE'; END IF;
 FOREACH target IN ARRAY ARRAY['admin_audit_logs','announcements','api_idempotency_records','app_capabilities','app_catalog','app_environments','app_prices','app_products','app_registry','app_role_grants','apps','artifacts','asset_exports','assistant_conversations','assistant_feedback','assistant_memory_summaries','assistant_messages','audio_assets','auth_challenges','baseline_history','baselines','bundle_app_access','bundle_plans','case_links','case_notes','cases','commerce_plans','commerce_prices','composition_caption_segments','composition_scene_assets','composition_scenes','connected_apps','copilot_conversations','copilot_messages','copilot_threads','crevox_sql_migrations','cross_app_callback_deliveries','data_sources','ecosystem_app_faqs','ecosystem_app_profiles','ecosystem_app_registry','ecosystem_user_links','ecosystem_workspace_links','email_delivery_intents','evidence_items','feature_flags','feature_limits','forum_badges','forum_bookmarks','forum_categories','forum_challenge_participants','forum_challenge_rewards','forum_challenge_tasks','forum_challenges','forum_moderation_actions','forum_profile_customization','forum_reactions','forum_replies','forum_reply_edits','forum_reports','forum_saved_searches','forum_search_documents','forum_subcategories','forum_tags','forum_thread_edits','forum_thread_tags','forum_threads','forum_user_badges','forum_user_stats','generated_3d_assets','issues','job_definitions','lipsync_jobs','log_entries','moderation_queue','monitored_wallets','oauth_accounts','operator_issues','pages','platform_role_grants','production_entities','production_entity_appearances','production_entity_hint_decisions','project_repositories','responsive_route_results','robot_devices','roles','security_public_summaries','security_remediation_prompts','security_score_history','security_target_verifications','signup_activation_states','sites','social_identities','stored_files','story_bibles','storyboards','support_assignments','support_conversations','supp